{
  "packet_id": "H6-T01-3",
  "claim_id": "C039",
  "status": "SUPPORTED",
  "claim": {
    "component_id": "C039.component",
    "value": "Trial outcomes should be compared with comparable baseline bookings while accounting for equipment, crew and demand differences.",
    "scope": "The proposed evaluation method; the mapping does not specify matching criteria or an adjustment procedure.",
    "provenance": {
      "refs": [
        {
          "source_id": "P027",
          "role": "SUPPORT"
        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "P027 directly states the comparison method and the differences to account for."
    }
  },
  "signal_basis": {
    "component_id": "C039.signal_basis",
    "value": "Prospectively observed trial outcomes include lateness frequency and duration, readiness and collection times, booking completion or displacement, workload and cleaning requirements. Comparison with comparable baseline bookings accounts for equipment, crew and demand differences; inadequate numbers of comparable bookings require further observation.",
    "scope": "Evaluation of the selected trial, with improvement supporting continued testing without independently establishing causation.",
    "provenance": {
      "refs": [
        {
          "source_id": "P021",
          "role": "SUPPORT"
        },
        {
          "source_id": "P027",
          "role": "SUPPORT"
        },
        {
          "source_id": "P035",
          "role": "SUPPORT"
        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "These spans supply the observed outcomes, baseline comparison, relevant differences, causal limitation and requirement for adequate comparable observations."
    }
  },
  "stated_empirical_relation": {
    "component_id": "C039.stated_empirical_relation",
    "value": "NOT_APPLICABLE",
    "scope": "NOT_APPLICABLE",
    "provenance": {
      "refs": [],
      "support_status": "SUFFICIENT",
      "rationale": "No conditional empirical relation is required for this supported methodological claim."
    }
  },
  "rationale": "Observed trial outcomes warrant comparison against a relevant baseline, with equipment, crew and demand differences considered because they can affect those outcomes. The claim recommends an evaluation method; it does not assert that any particular adjustment succeeds or that a comparison establishes causation.",
  "uncertainty": "Matching criteria and adjustment procedures remain unspecified, limiting assessment of implementation quality without undermining the bounded methodological recommendation.",
  "anomalies": []
}
